window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[101]={"id":"101","numero":101,"titre":"Paralysie faciale","objectifs":[{"id":"101-1","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître les différentes fonctions du nerf facial et savoir rechercher une anomalie","contenu":"<div class=\"notion-course\"><h4>Le VII est un nerf mixte</h4><table><thead><tr><th>Fonction</th><th>Support anatomique</th><th>Examen</th></tr></thead><tbody><tr><td>Motricité</td><td>Muscles peauciers de la face, platysma, stapédien ; également <span class=\"nc-pink_bg nc-bold\">stylohyoïdien</span> et ventre postérieur du <span class=\"nc-pink_bg nc-bold\">digastrique</span>.</td><td>Lever/froncer les sourcils, fermer les yeux contre résistance, montrer les dents, <span class=\"nc-yellow_bg\">gonfler les joues</span>.</td></tr><tr><td>Goût</td><td>VII bis, corde du tympan : deux tiers antérieurs de la langue.</td><td>Interroger sur dysgueusie, tester si utile. La sensibilité générale de cette langue relève du V3.</td></tr><tr><td>Sensibilité</td><td>Petit <span class=\"nc-green_bg nc-bold\">territoire</span> de la conque et du conduit auditif, zone de Ramsay-Hunt.</td><td>Inspecter et tester la sensibilité locale ; rechercher vésicules.</td></tr><tr><td>Sécrétion</td><td>Grand pétreux pour la lacrimation ; <span class=\"nc-yellow_bg\">corde du tympan</span> pour glandes submandibulaires/<span class=\"nc-purple nc-bold\">sublinguales</span>.</td><td>Rechercher sécheresse oculaire/buccale ; test de <span class=\"nc-blue nc-bold\">Schirmer</span> selon besoin.</td></tr></tbody></table><h4>Localiser sans confondre <span class=\"nc-red nc-bold\">moteur</span> et sensitif</h4><ul><li>Le <span class=\"nc-purple nc-bold\">noyau</span> <span class=\"nc-red nc-bold\">moteur</span> siège dans le pont. Le nerf traverse angle pontocérébelleux, conduit auditif interne et <span class=\"nc-blue_bg\">canal facial</span>, sort par le foramen stylomastoïdien puis se ramifie dans la parotide.</li><li>Le VII traverse la parotide mais n’en commande pas la sécrétion : celle-ci dépend du IX.</li><li>La cornée reçoit sa sensibilité du V1 ; le clignement efférent dépend du VII.</li><li>L’<span class=\"nc-blue_bg\">hyperacousie</span> traduit une atteinte du stapédien ; sécheresse et dysgueusie aident à situer une lésion proximale mais ne suffisent pas à une localisation millimétrique.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d941811aba5be90b8c1d16b6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Paralysie faciale (101)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-12-item-101-paralysie-faciale\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 101, chapitre 12</a></li></ul><p></p></details><details><summary>Situations de départ LiSA vérifiées</summary><ul><li><a href=\"https://livret.uness.fr/lisa/2026/Paralysie_faciale_SDD-127\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 127 · Paralysie faciale</a><ul><li>Différencier centrale/périphérique, éliminer urgence neurologique/ORL, localiser le VII.</li><li>Rechercher la cause ; traiter Bell et mettre en place la protection oculaire.</li></ul></li></ul><p>Pages et attendus consultés directement sur LiSA 2026 le 13 octobre 2026. Les arbres sont des synthèses pédagogiques ATLAS, avec source officielle de chaque étape.</p></details>","frequence":2},{"id":"101-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une paralysie faciale et distinguer sa nature périphérique ou centrale","contenu":"<div class=\"notion-course\"><h4>Examiner toute la face et tout le système neurologique</h4><table><thead><tr><th></th><th>Atteinte centrale supranucléaire</th><th>Atteinte périphérique du VII</th></tr></thead><tbody><tr><td>Répartition</td><td>Prédominance faciale inférieure <span class=\"nc-green_bg\">controlatérale</span> à la lésion ; relative épargne du front.</td><td>Front, œil et bouche homolatéraux à la lésion.</td></tr><tr><td>Mimique</td><td><span class=\"nc-yellow_bg\">Dissociation automatico-volontaire</span> possible : sourire spontané mieux conservé que sur ordre.</td><td>Déficit lors des mouvements volontaires et spontanés.</td></tr><tr><td>Associations</td><td>Hémiparésie, aphasie, autres signes focaux ; installation <span class=\"nc-red nc-bold\">brutale</span> = AVC à rechercher.</td><td>Isolée dans Bell, ou signes otologiques, sensitifs/viscéraux du VII, autres paires crâniennes selon la cause.</td></tr><tr><td>Piège</td><td>Une discrète faiblesse du front reste possible.</td><td>Une lésion du noyau/fascicule dans le pont donne un déficit de type périphérique avec d’autres signes centraux.</td></tr></tbody></table><ol><li>Comparer au repos puis à la mimique ; les photos antérieures aident si asymétrie ancienne.</li><li>Tester front, fermeture palpébrale contre résistance et bouche. Identifier <span class=\"nc-red nc-bold\">lagophtalmie</span>, effacement nasogénien et <span class=\"nc-blue_bg\">attraction de la bouche du côté</span> sain.</li><li>Rechercher déficit des membres, trouble de parole, regard, sensibilité, déglutition et audition ; examiner <span class=\"nc-blue_bg\">otoscopie</span>, conque et parotide.</li><li>Coter et documenter la gravité (House-Brackmann I <span class=\"nc-green_bg\">normal</span> à VI paralysie complète), surtout la protection cornéenne.</li></ol><div class=\"callout\"><p>Une fermeture oculaire déficiente oriente fortement vers le VII périphérique, mais le diagnostic topographique repose sur l’ensemble de l’examen. Ne pas écrire que l’examen neurologique est toujours <span class=\"nc-green_bg\">normal</span> dans une PFP.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d941811aba5be90b8c1d16b6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Paralysie faciale (101)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-12-item-101-paralysie-faciale\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 101, chapitre 12</a></li></ul><p></p></details>","frequence":0},{"id":"101-3","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie/vidéo d’une paralysie faciale périphérique (PFP)","contenu":"<div class=\"notion-course\"><h4>Lecture d’une vidéo de PFP</h4><p><a href=\"https://www.cen-neurologie.fr/videotheque/paralysie-faciale-peripherique\" target=\"_blank\" rel=\"noopener noreferrer\">Voir le support clinique du CEN ↗</a></p><table><thead><tr><th>Manœuvre</th><th>Signe à repérer</th></tr></thead><tbody><tr><td>Lever les sourcils</td><td>Diminution des rides et de l’élévation du sourcil du côté atteint.</td></tr><tr><td>Fermer fortement les yeux</td><td>Fermeture incomplète ; globe tournant vers le haut visible (Charles Bell). Dans forme fruste : cils plus visibles (Souques).</td></tr><tr><td>Montrer les dents / sourire</td><td>Attraction de la bouche vers le côté sain ; effacement du sillon nasogénien atteint.</td></tr><tr><td>Gonfler les joues</td><td>Fuite d’air du côté faible.</td></tr></tbody></table><p>Décrire d’abord le côté et les territoires atteints, puis conclure au type périphérique. L’apparence d’une PFP ne permet pas à elle seule d’affirmer Bell : examiner oreille, parotide et autres signes neurologiques.</p><div class=\"callout\"><p>Le <span class=\"nc-red nc-bold\">signe de Charles Bell</span> est la mise à découvert d’un mouvement protecteur du globe ; il n’identifie pas la cause de la paralysie.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d941811aba5be90b8c1d16b6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Paralysie faciale (101)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-12-item-101-paralysie-faciale\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 101, chapitre 12</a></li></ul><p></p></details>","frequence":6,"liens":[{"href":"https://radiopaedia.org/articles/facial-palsy","label":"Radiopaedia : Facial palsy"}]},{"id":"101-4","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie/vidéo d’une paralysie faciale centrale","contenu":"<div class=\"notion-course\"><h4>Reconnaître une prédominance faciale inférieure</h4><ul><li>Chute de la commissure et effacement du pli nasogénien ; bouche attirée vers le côté sain au sourire.</li><li>Plissement du front et fermeture palpébrale relativement préservés ; une atteinte supérieure discrète est possible.</li><li>Comparer mimique sur consigne et sourire spontané : <span class=\"nc-yellow_bg\">dissociation automatico-volontaire</span> possible.</li><li>Chercher immédiatement hémiparésie, aphasie, dysarthrie ou trouble visuel et dater le début.</li></ul><p>Le chapitre CEN décrit sa vidéo 12.1 de paralysie centrale gauche : <a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-12-item-101-paralysie-faciale\" target=\"_blank\" rel=\"noopener noreferrer\">ouvrir le chapitre et ses compléments ↗</a>. Le support externe est distinct de la grille de lecture ci-dessus.</p><div class=\"callout\"><p>Toute <span class=\"nc-blue_bg\">paralysie faciale</span> centrale récente impose une <span class=\"nc-blue nc-bold\">imagerie</span> cérébrale. En cas de début brutal, activer la filière AVC sans attendre une consultation programmée.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d941811aba5be90b8c1d16b6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Paralysie faciale (101)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-12-item-101-paralysie-faciale\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 101, chapitre 12</a></li></ul><p></p></details>","frequence":0},{"id":"101-5","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales causes de PFP","contenu":"<div class=\"notion-course\"><h4>Les causes selon le contexte et le trajet</h4><table><thead><tr><th>Contexte / siège</th><th>Causes à évoquer</th></tr></thead><tbody><tr><td>PFP aiguë isolée</td><td>Paralysie de Bell, après examen excluant une cause identifiable.</td></tr><tr><td>Pont</td><td>AVC, démyélinisation, tumeur ; PFP <span class=\"nc-green_bg\">homolatérale</span> avec signes des voies longues controlatéraux possible (syndrome alterne).</td></tr><tr><td>Angle pontocérébelleux / base</td><td>Schwannome vestibulaire, méningiome, tumeur/inflammation ou atteinte méningée ; souvent audition ou autres nerfs associés.</td></tr><tr><td>Oreille / rocher</td><td>Zona <span class=\"nc-purple nc-bold\">géniculé</span>, otite compliquée, cholestéatome, <span class=\"nc-orange nc-bold\">fracture du rocher</span>, iatrogénie chirurgicale.</td></tr><tr><td>Parotide / face</td><td>Tumeur, parotidite, traumatisme ou chirurgie du VII extracrânien.</td></tr><tr><td>Atteinte <span class=\"nc-red nc-bold\">bilatérale</span> / contexte général</td><td><span class=\"nc-orange nc-bold\">Guillain-Barré</span>, <span class=\"nc-purple nc-bold\">Lyme</span>, <span class=\"nc-purple nc-bold\">VIH</span>, <span class=\"nc-orange nc-bold\">sarcoïdose</span> et autres maladies inflammatoires ; <span class=\"nc-orange_bg\">diabète</span> selon contexte.</td></tr></tbody></table><h4>Associations évocatrices</h4><ul><li>Vésicules auriculaires + <span class=\"nc-blue_bg\">otalgie</span> + PFP : Ramsay-Hunt ; rechercher une atteinte cochléovestibulaire.</li><li>Morsure de tique/érythème migrant, douleurs radiculaires, syndrome méningé ou diplégie : rechercher une neuroborréliose.</li><li>Diplégie avec faiblesse des membres, aréflexie ou troubles bulbaires : SGB, surveillance respiratoire urgente.</li><li>Parotidite + uvéite + <span class=\"nc-blue_bg\">paralysie faciale</span>, avec ou sans <span class=\"nc-blue_bg\">fièvre</span> : syndrome de Heerfordt (sarcoïdose).</li><li>Récidives avec œdème orofacial et langue plicaturée : syndrome de Melkersson-Rosenthal.</li><li>La myasthénie peut produire une faiblesse faciale <span class=\"nc-red nc-bold\">bilatérale</span> ; c’est une atteinte de jonction, pas une lésion des nerfs VII.</li></ul><div class=\"callout\"><p>Progression, récidive <span class=\"nc-green_bg\">homolatérale</span>, déficit limité à une <span class=\"nc-blue_bg nc-bold\">branche</span>, masse ou autres paires crâniennes : ne pas conclure à une <span class=\"nc-blue_bg\">forme</span> idiopathique.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d941811aba5be90b8c1d16b6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Paralysie faciale (101)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-12-item-101-paralysie-faciale\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 101, chapitre 12</a></li></ul><p></p></details>","frequence":1},{"id":"101-6","rang":"A","rubrique":"Etiologies","titre":"Rechercher les arguments en faveur d’une paralysie faciale a frigore devant un déficit facial","contenu":"<div class=\"notion-course\"><h4>Bell : tableau compatible et absence d’autre cause</h4><ul><li>PFP unilatérale d’installation aiguë en heures à quelques jours, atteignant son maximum généralement en moins de 72 h.</li><li>Déficit <span class=\"nc-green_bg nc-bold\">facial</span> isolé ; douleurs rétroauriculaires, dysgueusie et <span class=\"nc-blue_bg\">hyperacousie</span> peuvent accompagner.</li><li><span class=\"nc-blue_bg\">Otoscopie</span>, inspection de la conque, palpation parotidienne et examen neurologique doivent chercher une autre cause.</li><li>Pas de traumatisme explicatif, de masse, de syndrome méningé ni d’atteinte cochléovestibulaire ou d’autres nerfs inexpliquée.</li></ul><h4>Bilan raisonné</h4><table><thead><tr><th>Donnée</th><th>Conduite</th></tr></thead><tbody><tr><td>Tableau typique isolé</td><td>Traitement précoce, protection oculaire et suivi ; bilan selon terrain et pratique spécialisée.</td></tr><tr><td>Atypie ou suspicion tumorale</td><td>IRM de tout le trajet du VII avec injection, incluant parotide ; évaluation rapide.</td></tr><tr><td>Bell présumée</td><td>Le CEN récent discute une IRM au premier mois ; elle devient indispensable en présence d’atypie. Ne pas retarder les corticoïdes pour l’obtenir.</td></tr><tr><td>Contexte orientant</td><td>Glycémie, <span class=\"nc-yellow_bg\">sérologie de Lyme</span>/VIH et LCS selon suspicion ; audiométrie si signes auditifs ou doute topographique.</td></tr></tbody></table><div class=\"callout\"><p>Le froid n’est pas une preuve étiologique. Bell reste un diagnostic d’exclusion suivi dans le temps : une évolution discordante fait rouvrir le bilan.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d941811aba5be90b8c1d16b6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Paralysie faciale (101)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-12-item-101-paralysie-faciale\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 101, chapitre 12</a></li></ul><p>La formulation « IRM systématique dans toute PFP » a été remplacée par les indications et la discussion précisées dans le CEN actuel.</p></details>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/bell-palsy","label":"Radiopaedia : Bell palsy"}]},{"id":"101-7","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge d’une paralysie faciale a frigore, y compris les complications","contenu":"<div class=\"notion-course\"><h4>Trois priorités : cornée, traitement précoce, suivi</h4><table><thead><tr><th>Mesure</th><th>Application</th></tr></thead><tbody><tr><td>Protection oculaire dès le diagnostic</td><td>Larmes artificielles le jour, gel/pommade et fermeture complète protégée la nuit si <span class=\"nc-red nc-bold\">lagophtalmie</span>. Vérifier que le dispositif ne frotte pas la cornée.</td></tr><tr><td>Corticothérapie</td><td>Chez l’adulte, prednisone/prednisolone environ 1 mg/kg/j pendant <span class=\"nc-pink nc-bold\">7–10 jours</span> selon protocole et terrain ; commencer au mieux dans les 72 h.</td></tr><tr><td>Antiviral</td><td>Discuté en association dans certaines formes sévères ; pas de remplacement de la corticothérapie par antiviral seul. En cas de zona, traitement antiviral spécifique indiqué.</td></tr><tr><td>Rééducation</td><td>Si forme sévère ou <span class=\"nc-red nc-bold\">séquelles</span> : thérapeute formé, exercices doux et contrôle des <span class=\"nc-red nc-bold\">syncinésies</span> ; éviter renforcement forcé et électrostimulation non indiquée.</td></tr><tr><td>Recours spécialisé</td><td>Déficit complet/persistant : ORL, éventuellement ENMG pronostique. Décompression du nerf : indication exceptionnelle discutée, pas un traitement automatique à trois semaines.</td></tr></tbody></table><h4>Complication cornéenne : agir vite</h4><ul><li>Œil rouge, douleur, photophobie ou baisse visuelle : examen ophtalmologique urgent, même si le traitement <span class=\"nc-green_bg nc-bold\">facial</span> vient de débuter.</li><li>Forme sévère, exposition persistante ou impossibilité d’appliquer la protection : mesures palpébrales spécialisées, parfois tarsorraphie temporaire.</li><li>Informer sur délai de <span class=\"nc-pink nc-bold\">récupération</span>, retentissement esthétique et psychologique ; contrôler tolérance et évolution.</li></ul><div class=\"callout\"><p>Biofeedback et électrostimulation ne sont pas synonymes : ne pas interdire globalement le contrôle visuel ou le biofeedback utilisés par des équipes spécialisées.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d941811aba5be90b8c1d16b6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Paralysie faciale (101)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-12-item-101-paralysie-faciale\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 101, chapitre 12</a></li></ul><p>Suppression d’une décompression présentée comme automatique et de la confusion entre électrostimulation et biofeedback.</p></details>","frequence":2},{"id":"101-8","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les évolutions possibles d’une paralysie faciale a frigore","contenu":"<div class=\"notion-course\"><h4>La <span class=\"nc-pink nc-bold\">récupération</span> se juge dans le temps</h4><ul><li>Le pronostic est généralement favorable, surtout si le déficit initial est incomplet et le traitement précoce.</li><li>Une amélioration peut débuter en une à deux semaines ; la <span class=\"nc-pink nc-bold\">récupération</span> se poursuit sur plusieurs semaines, parfois plusieurs mois.</li><li>Une paralysie <span class=\"nc-red nc-bold\">complète</span>, un âge plus élevé ou un terrain défavorable augmentent le risque de <span class=\"nc-red nc-bold\">séquelles</span>. Une <span class=\"nc-blue_bg\">surdité</span> ou un <span class=\"nc-blue_bg\">vertige</span> impose surtout de reconsidérer l’étiologie.</li><li>Absence d’amélioration après quelques semaines, aggravation ou récidive : réévaluer précocement, sans attendre six mois.</li></ul><table><thead><tr><th>Séquelle</th><th>Mécanisme / conduite</th></tr></thead><tbody><tr><td>Faiblesse résiduelle</td><td>Dénervation/réinnervation incomplète ; bilan spécialisé et rééducation.</td></tr><tr><td><span class=\"nc-red nc-bold\">Syncinésies</span></td><td>Contraction involontaire associée à un autre mouvement volontaire ; rééducation spécifique, <span class=\"nc-pink nc-bold\">toxine botulique</span> selon gêne.</td></tr><tr><td>Contracture / <span class=\"nc-red_bg nc-bold\">spasme</span> post-paralytique</td><td>Peut inverser l’asymétrie de repos ; prise en charge spécialisée.</td></tr><tr><td>Larmes de crocodile</td><td><span class=\"nc-orange nc-bold\">Larmoiement</span> au repas par <span class=\"nc-red nc-bold\">réinnervation aberrante</span>.</td></tr><tr><td>Kératite / ulcération</td><td>Exposition et sécheresse : maintien de la protection, urgence si symptômes oculaires.</td></tr></tbody></table><div class=\"callout\"><p>Ne pas promettre une <span class=\"nc-pink nc-bold\">récupération</span> « toujours <span class=\"nc-red nc-bold\">complète</span> » à partir du seul caractère incomplet initial.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d941811aba5be90b8c1d16b6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Paralysie faciale (101)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-12-item-101-paralysie-faciale\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 101, chapitre 12</a></li></ul><p></p></details>","frequence":2},{"id":"101-9","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie/vidéo d’un hémispasme facial post-paralytique","contenu":"<div class=\"notion-course\"><h4>Identifier une syncinésie post-paralytique</h4><p>Sur une séquence filmée, comparer le repos puis le sourire, le gonflement des joues et la fermeture des yeux. Exemple typique : l’œil se ferme involontairement quand le patient sourit.</p><ul><li>Antécédent de PFP avec <span class=\"nc-pink nc-bold\">récupération</span> incomplète, faiblesse résiduelle et contracture orientent vers une séquelle post-paralytique.</li><li>La co-contraction peut donner au repos l’impression que l’autre côté est <span class=\"nc-yellow_bg nc-bold\">paralysé</span>.</li><li>Distinguer du <span class=\"nc-red_bg nc-bold\">spasme</span> hémifacial primaire, souvent lié à un conflit neurovasculaire ; ne pas trancher sur la seule présence ou absence de clonies.</li><li>Le traitement associe rééducation spécialisée et, selon la gêne, injections de <span class=\"nc-pink nc-bold\">toxine botulique</span>.</li></ul><p>Le CEN référence une vidéo 12.3 : <a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-12-item-101-paralysie-faciale\" target=\"_blank\" rel=\"noopener noreferrer\">compléments du chapitre ↗</a>.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d941811aba5be90b8c1d16b6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Paralysie faciale (101)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-12-item-101-paralysie-faciale\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 101, chapitre 12</a></li></ul><p></p></details>","frequence":1},{"id":"101-10","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens d’imagerie devant une paralysie faciale","contenu":"<div class=\"notion-course\"><h4>Adapter l’<span class=\"nc-blue nc-bold\">imagerie</span> au siège suspecté</h4><table><thead><tr><th>Situation</th><th>Examen</th></tr></thead><tbody><tr><td>Début brutal et signes centraux</td><td><span class=\"nc-blue nc-bold\">Imagerie</span> neurovasculaire urgente selon filière AVC (TDM/angio-TDM ou IRM adaptée).</td></tr><tr><td>Autres nerfs crâniens, syndrome alterne, cause inflammatoire/tumorale</td><td><span class=\"nc-brown_bg\">IRM cérébrale</span>, tronc et angles pontocérébelleux avec séquences adaptées.</td></tr><tr><td>PFP atypique, <span class=\"nc-red nc-bold\">récidivante</span> ou <span class=\"nc-blue_bg nc-bold\">progressive</span></td><td>IRM injectée du trajet complet du VII, y compris portion parotidienne.</td></tr><tr><td>Bell présumée sans atypie</td><td>IRM du trajet discutée au premier mois selon CEN/avis ORL ; traitement et suivi commencent immédiatement.</td></tr><tr><td>Traumatisme / otorrhée / cholestéatome</td><td><span class=\"nc-brown_bg\">TDM des rochers</span> pour lésions osseuses et extension ; examens additionnels selon contexte.</td></tr><tr><td>Masse parotidienne</td><td><span class=\"nc-blue nc-bold\">Imagerie</span> parotidienne/cervicale, notamment IRM ; bilan ORL de la masse.</td></tr></tbody></table><h4>Et l’électrophysiologie ?</h4><ul><li><span class=\"nc-blue nc-bold\">ENMG</span> surtout dans les formes sévères complètes ou persistantes, pour documenter dénervation et réinnervation.</li><li>Sa valeur dépend du délai depuis le début : l’examen trop précoce ne prédit pas toute l’atteinte axonale. Le calendrier est fixé par le spécialiste.</li><li>Une non-<span class=\"nc-pink nc-bold\">récupération</span> ou une nouvelle anomalie impose une réévaluation même si la première <span class=\"nc-blue nc-bold\">imagerie</span> était rassurante.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d941811aba5be90b8c1d16b6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Paralysie faciale (101)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-12-item-101-paralysie-faciale\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 101, chapitre 12</a></li></ul><p></p></details>","frequence":0},{"id":"101-11","rang":"A","rubrique":"Contenu multimédia","titre":"Iconographie clinique d’un exemple typique d’une PFP unilatérale","contenu":"<div class=\"notion-course\"><h4>Méthode de lecture d’une PFP unilatérale</h4><p><a href=\"https://www.cen-neurologie.fr/videotheque/paralysie-faciale-peripherique\" target=\"_blank\" rel=\"noopener noreferrer\">Ouvrir le cas vidéo du CEN ↗</a></p><ol><li>Nommer le côté atteint à partir du front, de la fermeture palpébrale et de la bouche, et non de la seule direction de traction du sourire.</li><li>Décrire les signes au repos puis lors de chaque consigne ; préciser si l’œil se ferme <span class=\"nc-green nc-bold\">complètement</span>.</li><li>Conclure au type périphérique si les territoires <span class=\"nc-green_bg nc-bold\">supérieur</span> et <span class=\"nc-red_bg nc-bold\">inférieur</span> sont concordants.</li><li>Rechercher hors image les signes d’étiologie : <span class=\"nc-blue_bg\">otalgie</span>/éruption, surdité, traumatisme, masse, signes neurologiques.</li><li>Énoncer la protection cornéenne si <span class=\"nc-red nc-bold\">lagophtalmie</span>.</li></ol><div class=\"callout\"><p>Une image de PFP ne suffit pas à diagnostiquer une paralysie de Bell.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d941811aba5be90b8c1d16b6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Paralysie faciale (101)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-12-item-101-paralysie-faciale\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 101, chapitre 12</a></li></ul><p></p></details>","frequence":1},{"id":"101-12","rang":"A","rubrique":"Contenu multimédia","titre":"Iconographie clinique d’un exemple typique d’une éruption vésiculaire de la conque en faveur d’une PFP zostérienne","contenu":"<div class=\"notion-course\"><h4><span class=\"nc-purple_bg\">Zona du ganglion géniculé</span> : Ramsay-Hunt</h4><figure><img src=\"https://www.cen-neurologie.fr/sites/www.cen-neurologie.fr/files/medias/images/xhtml/B9782294786075500212_f12-02-9782294786075.jpg\" alt=\"CEN, figure 12.2 : vésicules et croûte du pavillon de l’oreille. Source : Dr E. Sauvaget, ORL.\" loading=\"lazy\"><figcaption>CEN, figure 12.2 : vésicules et croûte du pavillon de l’oreille. Source : Dr E. Sauvaget, ORL.</figcaption></figure><ul><li>Inspecter conque, conduit auditif externe et tympan : vésicules douloureuses dans la zone de Ramsay-Hunt, parfois discrètes ou décalées dans le temps.</li><li>PFP souvent sévère, <span class=\"nc-blue_bg\">otalgie</span> importante ; rechercher hypoacousie, acouphènes, <span class=\"nc-blue_bg\">vertige</span> et atteinte d’autres nerfs.</li><li>L’absence initiale d’éruption n’exclut pas toute atteinte zostérienne. Le diagnostic associe clinique et contexte.</li><li>Avis ORL rapide, antiviral (<span class=\"nc-pink_bg\">valaciclovir</span>/<span class=\"nc-pink_bg\">aciclovir</span> selon terrain et protocole), corticothérapie selon indication et protection cornéenne.</li><li><span class=\"nc-pink nc-bold\">Récupération</span> souvent moins bonne que Bell ; surveillance motrice, auditive et oculaire.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d941811aba5be90b8c1d16b6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Paralysie faciale (101)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-12-item-101-paralysie-faciale\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 101, chapitre 12</a></li></ul><p></p></details>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/geniculate-ganglion","label":"Radiopaedia : Geniculate ganglion"}]},{"id":"101-13","rang":"B","rubrique":"Contenu multimédia","titre":"Iconographie clinique d’un exemple typique d’une tumeur parotidienne compliquée d’une PFP","contenu":"<div class=\"notion-course\"><h4>Masse parotidienne et déficit <span class=\"nc-green_bg nc-bold\">facial</span> : penser tumeur</h4><figure><img src=\"https://www.cen-neurologie.fr/sites/www.cen-neurologie.fr/files/medias/images/xhtml/B9782294786075500212_f12-03-9782294786075.jpg\" alt=\"CEN, figure 12.3 : IRM d’une tumeur parotidienne droite compliquée de PFP. Source : Dr E. Sauvaget, ORL.\" loading=\"lazy\"><figcaption>CEN, figure 12.3 : IRM d’une tumeur parotidienne droite compliquée de PFP. Source : Dr E. Sauvaget, ORL.</figcaption></figure><ul><li>Palper la région pré-auriculaire et rétromandibulaire, rechercher induration, fixation, douleur et adénopathies cervicales.</li><li>Une <span class=\"nc-blue_bg\">paralysie faciale</span> associée à une masse parotidienne est un signe de gravité, notamment de malignité.</li><li>Une évolution <span class=\"nc-blue_bg nc-bold\">progressive</span>, une atteinte limitée à une <span class=\"nc-blue_bg nc-bold\">branche</span> ou une récidive <span class=\"nc-green_bg\">homolatérale</span> renforcent l’alerte ; un début brusque n’exclut pas une tumeur.</li><li>Avis ORL et <span class=\"nc-blue nc-bold\">imagerie</span> parotidienne/cervicale ; prélèvement de la masse selon stratégie spécialisée.</li><li>Ne pas remplacer le bilan tumoral par une simple prescription de corticoïdes pour Bell.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d941811aba5be90b8c1d16b6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Paralysie faciale (101)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-12-item-101-paralysie-faciale\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 101, chapitre 12</a></li></ul><p></p></details>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/mucoepidermoid-carcinoma-of-salivary-glands","label":"Radiopaedia : Mucoepidermoid carcinoma (glandes salivaires)"}]},{"id":"101-14","rang":"B","rubrique":"Contenu multimédia","titre":"Illustration de l’anatomie fonctionnelle du nerf facial","contenu":"<div class=\"notion-course\"><h4>Suivre le VII du pont aux muscles</h4><table><thead><tr><th>Segment / <span class=\"nc-blue_bg nc-bold\">branche</span></th><th>Repère fonctionnel</th></tr></thead><tbody><tr><td>Commande cortico-nucléaire</td><td>Projection <span class=\"nc-red nc-bold\">bilatérale</span> vers le <span class=\"nc-green_bg nc-bold\">facial</span> <span class=\"nc-green_bg nc-bold\">supérieur</span>, surtout croisée vers le <span class=\"nc-green_bg nc-bold\">facial</span> <span class=\"nc-red_bg nc-bold\">inférieur</span> : explique la prédominance inférieure d’une atteinte supranucléaire.</td></tr><tr><td>Noyau/fascicule pontique</td><td>Lésion donnant une paralysie de type périphérique, avec signes centraux associés possibles.</td></tr><tr><td>Angle pontocérébelleux / conduit auditif interne</td><td>VII et VII bis au voisinage du VIII : chercher audition et équilibre.</td></tr><tr><td><span class=\"nc-green nc-bold\">Segment labyrinthique</span>, <span class=\"nc-yellow_bg\">genou</span>/<span class=\"nc-green nc-bold\">ganglion géniculé</span></td><td>Départ du grand pétreux ; atteinte proximale pouvant altérer lacrimation.</td></tr><tr><td>Segments tympanique puis <span class=\"nc-red nc-bold\">mastoïdien</span></td><td>Branches du stapédien puis <span class=\"nc-purple nc-bold\">corde du tympan</span> : <span class=\"nc-blue_bg\">hyperacousie</span>, goût et sécrétions selon niveau.</td></tr><tr><td>Foramen stylomastoïdien puis parotide</td><td>Ramifications motrices vers la face ; lésion distale souvent purement motrice.</td></tr></tbody></table><h4>Trois pièges anatomiques</h4><ul><li>Le VII <span class=\"nc-red nc-bold\">moteur</span> ferme la paupière, le III relève la paupière : ne pas confondre <span class=\"nc-red nc-bold\">lagophtalmie</span> et ptosis.</li><li>La sensibilité cornéenne est V1 ; l’efférence du réflexe cornéen est VII.</li><li>Goût antérieur de langue : VII bis ; sensibilité générale : V3 ; sécrétion parotidienne : IX.</li></ul><p>Le tableau anatomique reste lisible dans les pop-up et sous l’arbre ; les références permettent d’ouvrir l’iconographie anatomique <span class=\"nc-pink nc-bold\">complète</span>.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d941811aba5be90b8c1d16b6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Paralysie faciale (101)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-12-item-101-paralysie-faciale\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 101, chapitre 12</a></li></ul><p></p></details>","frequence":0}],"astuces":[{"type":"piege","titre":"Front : une règle relative","contenu":"<div class=\"notion-course\"><p>Une discrète atteinte supérieure est possible dans une PF centrale.</p></div>"},{"type":"piege","titre":"Deux urgences à ne pas oublier","contenu":"<div class=\"notion-course\"><p>Début brutal avec signes centraux : AVC ; œil exposé symptomatique : cornée.</p></div>"}],"strategie":{"urgence":"<div class=\"notion-course\"><ul><li>AVC si déficit central brutal ; avis ophtalmologique si œil rouge/douloureux ou baisse visuelle.</li></ul></div>","hospit":"<div class=\"notion-course\"><ul><li>Selon atteinte centrale, infection compliquée, trauma ou menace bulbaire/respiratoire associée.</li></ul></div>","redflags":"<div class=\"notion-course\"><ul><li>Masse, récidive <span class=\"nc-green_bg\">homolatérale</span>, progression, atteinte de <span class=\"nc-blue_bg nc-bold\">branche</span> ou autres paires crâniennes.</li></ul></div>","principes":"<div class=\"notion-course\"><ul><li>Localiser, protéger la cornée, traiter Bell précocement si diagnostic retenu, explorer les atypies.</li></ul></div>","suivi":"<div class=\"notion-course\"><ul><li>Documenter fermeture oculaire et <span class=\"nc-pink nc-bold\">récupération</span> ; revoir sans attendre six mois si évolution défavorable.</li></ul></div>"},"liensGlobaux":[{"href":"https://app.notion.com/p/1cb37f85d941811aba5be90b8c1d16b6?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-12-item-101-paralysie-faciale","label":"CEN · Item 101, chapitre 12 ↗"},{"href":"https://livret.uness.fr/lisa/2026/Paralysie_faciale_SDD-127","label":"LiSA · SDD 127 — Paralysie faciale ↗"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Quelle répartition et quels signes associés ?","detail":"<ul><li>Tester front, fermeture des yeux et bouche.</li><li>Dater début ; examiner membres, parole, regard et déglutition.</li></ul>","branches":[{"label":"Début brutal avec signes centraux","to":"avc"},{"label":"Déficit de type périphérique","to":"peripherique"},{"label":"Localisation incertaine","to":"doute"}]},{"id":"avc","kind":"urgent","label":"Activer la filière AVC","detail":"<ul><li>Dernière heure normale et imagerie neurovasculaire urgente.</li><li>Une lésion pontique peut donner une PF de type périphérique.</li></ul>","branches":[]},{"id":"peripherique","kind":"decision","label":"Protéger la cornée et examiner tout le trajet du VII","detail":"<ul><li>Rechercher lagophtalmie et symptômes oculaires.</li><li>Otoscopie, vésicules, audition, parotide et autres nerfs.</li></ul>","branches":[{"label":"Zona / otite / traumatisme / masse / atypie","to":"cause"},{"label":"PFP aiguë isolée compatible avec Bell","to":"bell"}]},{"id":"cause","kind":"finish","label":"Bilan et traitement ciblés","detail":"<ul><li>Avis ORL/neurologique selon contexte.</li><li>IRM du trajet, TDM rochers ou bilan infectieux selon hypothèse.</li><li>Ramsay-Hunt : antiviral et prise en charge précoce ; masse parotidienne avec PF : rechercher tumeur. Diplégie : évoquer Lyme, Guillain-Barré ou autre cause.</li></ul>","branches":[]},{"id":"bell","kind":"finish","label":"Bell reste un diagnostic après examen","detail":"<ul><li>Corticoïdes précoces si indiqués ; protection oculaire immédiate.</li><li>IRM discutée au premier mois selon CEN, systématiquement reconsidérée si atypie.</li></ul>","branches":[]},{"id":"doute","kind":"uncertain","label":"Compléter localisation et étiologie rapidement","detail":"<ul><li>Ne pas conclure Bell par défaut.</li><li>Priorité aux urgences neurologiques, ORL et ophtalmologiques.</li></ul>","branches":[]}]},"cards":[{"i":"c8b01e2a5bd0","n":101,"o":"101-1","u":"Eléments physiopathologiques","t":"Connaître les différentes fonctions du nerf facial et savoir rechercher une anomalie","q":"Quel nerf porte la sensibilité cornéenne et lequel ferme l’œil au réflexe cornéen ?","a":"<div class=\"notion-course\"><ul><li>Afférence : V1.</li><li>Efférence motrice de l’orbiculaire : VII.</li></ul></div>"},{"i":"1c4cf143f544","n":101,"o":"101-1","u":"Eléments physiopathologiques","t":"Connaître les différentes fonctions du nerf facial et savoir rechercher une anomalie","q":"Le nerf facial innerve-t-il la sécrétion de la parotide qu’il traverse ?","a":"<div class=\"notion-course\"><ul><li>Non : la sécrétion parotidienne dépend du IX.</li><li>Le VII se ramifie dans la glande pour la motricité faciale.</li></ul></div>"},{"i":"f0b6c54f4048","n":101,"o":"101-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une paralysie faciale et distinguer sa nature périphérique ou centrale","q":"PFP droite et hémiparésie gauche : quelle localisation évoquer ?","a":"<div class=\"notion-course\"><ul><li>Lésion pontique droite atteignant VII et voie longue.</li><li>Le type périphérique du déficit <span class=\"nc-green_bg nc-bold\">facial</span> n’exclut pas une lésion centrale du tronc.</li></ul></div>"},{"i":"07610d5dd891","n":101,"o":"101-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une paralysie faciale et distinguer sa nature périphérique ou centrale","q":"Une atteinte discrète du front exclut-elle une PF centrale ?","a":"<div class=\"notion-course\"><ul><li>Non : la prédominance inférieure est typique, mais l’épargne supérieure n’est pas absolue.</li></ul></div>"},{"i":"ad7cf638cf39","n":101,"o":"101-3","u":"Contenu multimédia","t":"Photographie/vidéo d’une paralysie faciale périphérique (PFP)","q":"Sur une vidéo, la bouche est attirée à gauche et l’œil droit se ferme mal. Quel côté est atteint ?","a":"<div class=\"notion-course\"><ul><li>Côté droit : l’attraction se fait vers le côté <span class=\"nc-yellow_bg nc-bold\">sain</span>.</li></ul></div>"},{"i":"431eba33e2ea","n":101,"o":"101-4","u":"Contenu multimédia","t":"Photographie/vidéo d’une paralysie faciale centrale","q":"PF inférieure brutale avec difficulté à parler : quelle conduite immédiate ?","a":"<div class=\"notion-course\"><ul><li>Activer la filière AVC et dater le début.</li><li><span class=\"nc-blue nc-bold\">Imagerie</span> urgente, même si le front est relativement préservé.</li></ul></div>"},{"i":"f69c9b7ffc2b","n":101,"o":"101-5","u":"Etiologies","t":"Connaître les principales causes de PFP","q":"Diplégie faciale, aréflexie et faiblesse ascendante : quel diagnostic prioritaire ?","a":"<div class=\"notion-course\"><ul><li>Syndrome de <span class=\"nc-orange nc-bold\">Guillain-Barré</span>.</li><li>Évaluer déglutition et respiration en urgence.</li></ul></div>"},{"i":"92f0daa48c73","n":101,"o":"101-6","u":"Etiologies","t":"Rechercher les arguments en faveur d’une paralysie faciale a frigore devant un déficit facial","q":"Quels examens cliniques précèdent l’étiquette « Bell » ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-blue_bg\">Otoscopie</span> et inspection de la conque.</li><li>Palpation parotidienne et examen neurologique complet.</li></ul></div>"},{"i":"e2f6abc3224e","n":101,"o":"101-6","u":"Etiologies","t":"Rechercher les arguments en faveur d’une paralysie faciale a frigore devant un déficit facial","q":"Une PFP progressive avec masse parotidienne est-elle compatible avec une simple Bell ?","a":"<div class=\"notion-course\"><ul><li>C’est une atypie : rechercher une <span class=\"nc-orange_bg\">cause tumorale</span> par bilan ORL et <span class=\"nc-blue nc-bold\">imagerie</span>.</li></ul></div>"},{"i":"8c227024e95b","n":101,"o":"101-7","u":"Prise en charge","t":"Connaître les principes de prise en charge d’une paralysie faciale a frigore, y compris les complications","q":"Quel traitement ne doit pas attendre le résultat d’une IRM dans une Bell typique récente ?","a":"<div class=\"notion-course\"><ul><li>Protection cornéenne et corticothérapie précoce si indiquée.</li><li>Bénéfice maximal de l’introduction dans les 72 h.</li></ul></div>"},{"i":"82abb1a3ce9c","n":101,"o":"101-7","u":"Prise en charge","t":"Connaître les principes de prise en charge d’une paralysie faciale a frigore, y compris les complications","q":"PFP avec œil rouge douloureux : quelle priorité ?","a":"<div class=\"notion-course\"><ul><li>Examen ophtalmologique urgent pour kératite/ulcération d’exposition.</li></ul></div>"},{"i":"fafa1936b1c9","n":101,"o":"101-8","u":"Suivi et/ou pronostic","t":"Connaître les évolutions possibles d’une paralysie faciale a frigore","q":"Aucune amélioration après plusieurs semaines de PFP : attendre six mois ?","a":"<div class=\"notion-course\"><ul><li>Non : réévaluer dès ce stade l’étiologie et la gravité avec le spécialiste.</li></ul></div>"},{"i":"b326f75a2930","n":101,"o":"101-9","u":"Contenu multimédia","t":"Photographie/vidéo d’un hémispasme facial post-paralytique","q":"L’œil se ferme involontairement au sourire après une ancienne PFP. Quel terme ?","a":"<div class=\"notion-course\"><ul><li>Syncinésie post-paralytique par <span class=\"nc-red nc-bold\">réinnervation aberrante</span>.</li></ul></div>"},{"i":"7fa6ea085d1e","n":101,"o":"101-10","u":"Examens complémentaires","t":"Connaître les indications des examens d’imagerie devant une paralysie faciale","q":"PFP après traumatisme avec otorragie : quelle imagerie osseuse ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-brown_bg\">TDM des rochers</span>, avec bilan traumatique et ORL adapté.</li></ul></div>"},{"i":"672a0a9f0c3a","n":101,"o":"101-11","u":"Contenu multimédia","t":"Iconographie clinique d’un exemple typique d’une PFP unilatérale","q":"La photographie d’une PFP permet-elle d’affirmer sa cause idiopathique ?","a":"<div class=\"notion-course\"><ul><li>Non : elle renseigne sur côté et topographie.</li><li>Le <span class=\"nc-gray_bg nc-bold\">diagnostic étiologique</span> exige interrogatoire et examen complet.</li></ul></div>"},{"i":"73d605807af6","n":101,"o":"101-12","u":"Contenu multimédia","t":"Iconographie clinique d’un exemple typique d’une éruption vésiculaire de la conque en faveur d’une PFP zostérienne","q":"PFP, otalgie sévère et vésicules de la conque : diagnostic ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-purple_bg\">Zona du ganglion géniculé</span>, syndrome de Ramsay-Hunt.</li></ul></div>"},{"i":"76a8f2c0991a","n":101,"o":"101-13","u":"Contenu multimédia","t":"Iconographie clinique d’un exemple typique d’une tumeur parotidienne compliquée d’une PFP","q":"Quel sens donner à une PFP associée à une masse parotidienne ?","a":"<div class=\"notion-course\"><ul><li>Signe de gravité tumorale, notamment de malignité.</li><li>Bilan ORL rapide.</li></ul></div>"},{"i":"34e901bebcfe","n":101,"o":"101-14","u":"Contenu multimédia","t":"Illustration de l’anatomie fonctionnelle du nerf facial","q":"Ptosis et lagophtalmie relèvent-ils du même nerf ?","a":"<div class=\"notion-course\"><ul><li>Non : ptosis par atteinte du releveur, nerf III.</li><li><span class=\"nc-red nc-bold\">Lagophtalmie</span> par déficit de l’orbiculaire, nerf VII.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/1cb37f85d941811aba5be90b8c1d16b6?pvs=204","reviewedAt":"2026-10-13","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif.","sddVerifiedAt":"2026-10-13","sdd":[{"number":127,"title":"Paralysie faciale","url":"https://livret.uness.fr/lisa/2026/Paralysie_faciale_SDD-127"}]}};
